// Local concept interfaces. No wallet, network, AI or transaction calls.
import {getLanguage} from './locales/locale.mjs';
import {simulate,CAPITAL} from './long-term.mjs';
import {journeyStart} from './experiment.mjs';

const t=(zh,en)=>getLanguage()==='en'?en:zh;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const signed=n=>(n>=0||Math.abs(n)<.005?'+':'−')+money(Math.abs(n));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#3947f5','#008c7b','#98a9d9','#b99c63'];
const labels=()=>['Core LP','Active LP',t('直接持股','Direct shares'),t('现金储备','Cash reserve')];
export const CONCEPT_GOALS={growth:[20,5,70,5],income:[35,20,35,10]};
export function conceptDefaults(){return {
  vault:{step:0,amount:10000,draftAmount:'10000',configured:false,event:'range'},
  agent:{step:0,amount:10000,draftAmount:'10000',asset:'CIRCLE',draftAsset:'CIRCLE',goal:'growth',draftGoal:'growth',mode:'manual',draftMode:'manual',limit:10,draftLimit:'10',configured:false,authorized:false,paused:false,event:'range',ran:false}
};}
function checkedAmount(v){const n=Number(v);if(!String(v).trim()||!Number.isFinite(n)||n<100||n>1000000||Math.abs(n*100-Math.round(n*100))>1e-7)throw new Error('Invalid preview amount');return n;}
export function submitConcept(ui,kind,stage,values){
  if(!['vault','agent'].includes(kind))throw new Error('Unknown concept');
  const next=structuredClone(ui),s=next[kind];
  if(stage==='setup'){
    s.amount=checkedAmount(values.amount);s.draftAmount=String(s.amount);
    if(kind==='agent'){
      const asset=String(values.asset??'').trim().toUpperCase();
      if(!/^[A-Z][A-Z0-9.\-]{0,11}$/.test(asset)||!Object.hasOwn(CONCEPT_GOALS,values.goal))throw new Error('Invalid asset or goal');
      s.asset=asset;s.draftAsset=asset;s.goal=values.goal;s.draftGoal=values.goal;s.authorized=false;s.ran=false;s.paused=false;
    }
    s.configured=true;s.step=1;
  }else if(kind==='agent'&&stage==='permissions'&&s.configured){
    if(!['manual','agent'].includes(values.mode)||![5,10,20].includes(Number(values.limit)))throw new Error('Invalid permission preview');
    s.mode=values.mode;s.draftMode=values.mode;s.limit=Number(values.limit);s.draftLimit=String(s.limit);
    s.authorized=true;s.paused=false;s.ran=false;s.step=2;
  }else throw new Error('Invalid preview stage');
  return next;
}
export function conceptAction(ui,kind,action,value){
  const next=structuredClone(ui),s=next[kind];if(!s)return next;
  if(action==='step'){
    const step=Number(value),allowed=step===0||s.configured&&(step===1||step===2&&(kind==='vault'||s.authorized));
    if(Number.isInteger(step)&&allowed)s.step=step;
  }
  if(action==='event'&&['range','fundamental','unverified'].includes(value)){s.event=value;s.ran=false;}
  if(kind==='agent'&&s.authorized){
    if(action==='pause'){s.paused=!s.paused;s.ran=false;}
    if(action==='run')s.ran=true;
    if(action==='revoke'){s.authorized=false;s.paused=false;s.ran=false;s.step=1;}
  }
  return next;
}
// Amount-based scaling only: report reuses one fixed, frictionless simulation.
let samplePoint;
export function vaultReport(amount){
  checkedAmount(amount);
  samplePoint??=simulate(journeyStart()).points[365];
  const scale=amount/CAPITAL,p=samplePoint;
  return {capital:amount,nav:p.nav*scale,holding:p.holdingPnl*scale,il:p.il*scale,management:p.management*scale,fees:p.fees*scale,
    sleeves:p.sleeves.map(v=>v*scale),feeCash:p.feeCash*scale,price:p.price};
}
export function agentDecision(s){
  if(!s.authorized)return 'not-authorized';
  if(s.paused)return 'paused';
  if(s.asset!=='CIRCLE')return 'needs-research';
  if(s.event==='unverified')return 'watch';
  if(s.event==='fundamental')return 'review';
  if(s.mode==='manual')return 'manual';
  return s.limit<8?'over-limit':'within-limit';
}

const button=(kind,action,value,label,cls='secondary',disabled=false)=>`<button type="button" class="${cls}" data-concept="${kind}" data-concept-action="${action}" data-concept-value="${value}" ${disabled?'disabled':''}>${label}</button>`;
const options=(pairs,value)=>pairs.map(([key,label])=>`<option value="${key}" ${String(value)===String(key)?'selected':''}>${label}</option>`).join('');
const amountField=(kind,s)=>`<label class="concept-field" for="${kind}-amount">${t('起始资金 · USDC','Starting capital · USDC')}<div class="concept-amount"><input id="${kind}-amount" name="amount" type="number" min="100" max="1000000" step="0.01" required value="${esc(s.draftAmount)}" data-concept-kind="${kind}" data-concept-field="draftAmount"><span>USDC</span></div><small>${t('演示范围 100–1,000,000；按 1 USDC = $1 展示','Preview range 100–1,000,000; shown at 1 USDC = $1')}</small></label>`;
function allocation(amount,weights){return `<div class="concept-allocation"><div class="concept-allocation-bar" aria-hidden="true">${weights.map((w,i)=>`<i style="width:${w}%;background:${colors[i]}"></i>`).join('')}</div><div class="concept-allocation-key">${weights.map((w,i)=>`<div><span><i style="background:${colors[i]}"></i>${labels()[i]}</span><b>${w.toFixed(1)}%</b><small>${money(amount*w/100)}</small></div>`).join('')}</div></div>`;}
function steps(kind,s){const names=kind==='vault'?[t('模拟存入','Deposit preview'),t('查看报表','View report'),t('运行机制','Operations')]:[t('设置目标','Set objectives'),t('方案与权限','Plan & permissions'),t('持续运行','Ongoing operation')];return `<nav class="concept-steps" aria-label="${t('产品预览步骤','Product preview steps')}">${names.map((name,i)=>`<button type="button" data-concept="${kind}" data-concept-action="step" data-concept-value="${i}" ${s.step===i?'aria-current="step"':''} ${i>0&&!s.configured||kind==='agent'&&i===2&&!s.authorized?'disabled':''}><span>0${i+1}</span>${name}</button>`).join('')}</nav>`;}
const events=(kind,s)=>`<div class="concept-events"><span>${t('假设出现一条新信息','Try an incoming event')}</span><div class="flow-choices">${[['range',t('价格偏离区间','Price leaves range')],['fundamental',t('经营预期大幅改变','Business outlook shifts')],['unverified',t('未经核实的新闻','Unverified news')]].map(([v,label])=>`<button type="button" data-concept="${kind}" data-concept-action="event" data-concept-value="${v}" aria-pressed="${s.event===v}">${label}</button>`).join('')}</div></div>`;
const buildList=(kind)=>`<details class="concept-details"><summary>${t('从现有 Demo 到可运行产品，还需要什么','From this demo to a working product')}</summary><div><p><b>${t('已有基础','Existing foundation')}</b> · ${t('有来源的财务底稿、估值模型、AI 候选记录、AMM 核算及 CIRCLE 仓位监控。','Sourced financial inputs, valuation models, archived AI proposals, AMM calculations and CIRCLE position monitoring.')}</p><p><b>${t('下一步研发','Next engineering work')}</b> · ${kind==='vault'?t('池子扫描与协议适配、金库合约、份额记账、申赎队列、策略权限、容量与安全验证。','Pool discovery and protocol adapters, vault contracts, share accounting, redemption queues, strategy permissions, capacity and security validation.'):t('新资产研究模板、用户隔离与任务调度、钱包权限与撤销、交易模拟、签名执行、故障暂停及链上对账。','Research templates for new assets, isolated user jobs, wallet permissions and revocation, transaction simulation, signing, failure handling and on-chain reconciliation.')}</p><button class="text-button" data-proof="map">${t('查看已有 AI 工作流','Inspect the existing AI workflow')} ↗</button></div></details>`;

function vaultSetup(s){return `<section class="panel concept-panel"><div class="concept-product"><span class="concept-symbol" aria-hidden="true">V</span><div><h2>CIRCLE Valuation Vault</h2><p>${t('一套研究驱动的股票、LP 与现金策略','One research-led strategy for shares, LPs and cash')}</p></div><span class="badge">${t('产品设想','Product concept')}</span></div><form data-concept-form="vault" data-concept-stage="setup">${amountField('vault',s)}<div class="concept-receipt"><span>${t('演示初始份额净值','Illustrative starting NAV per share')}</span><b>$1.00</b><span>${t('未来拟支持资产','Planned deposit asset')}</span><b>USDC · Solana</b></div><button type="submit" class="primary">${t('模拟存入，查看管理方式','Preview deposit & management')} →</button><p class="flow-caption">${t('仅生成本地演示份额，不连接钱包或接收资金','Creates local preview shares only. No wallet connection or funds accepted.')}</p></form></section><section class="panel concept-panel"><h2>${t('一次存入，持续管理','Deposit once. Manage over time.')}</h2><ol class="concept-list"><li><b>${t('共同策略','Shared mandate')}</b><p>${t('先约定资产范围与风险边界，再由同一套规则管理金库持仓。','Define eligible assets and risk limits, then manage holdings under one mandate.')}</p></li><li><b>${t('研究驱动复核','Research-led review')}</b><p>${t('定期审视估值；新闻或价格异动触发复核，确认后再调整 LP、持股与现金。','Review valuations regularly. News and price events trigger checks before changing LPs, shares or cash.')}</p></li><li><b>${t('按份额核算','Share-based accounting')}</b><p>${t('每份净值反映股票、现金和费用；申赎按可用流动性与队列处理。','Each share reflects stocks, cash and fees. Redemptions depend on available liquidity and a withdrawal queue.')}</p></li></ol></section>`;}
function vaultStatement(s){const r=vaultReport(s.amount),weights=[38.95,20,37.21,3.84];return `<section class="panel concept-panel"><div class="row"><h2>${t('模拟存入记录','Preview deposit receipt')}</h2><span class="badge">${t('本地生成','Local preview')}</span></div><div class="concept-metrics"><div><span>${t('模拟本金','Preview capital')}</span><strong>${money(s.amount)}</strong></div><div><span>${t('初始演示份额','Starting preview shares')}</span><strong>${s.amount.toLocaleString('en-US',{maximumFractionDigits:2})}</strong></div></div>${allocation(s.amount,weights)}<p class="flow-caption">${t('沿用 CIRCLE 历史比例，按演示起价 $92.02 重建持仓；不是实盘金库。初始份额净值为 $1。','Reuses CIRCLE’s historical weights with positions reinitialized at the $92.02 demo start. Not a live vault. Starting preview NAV per share is $1.')}</p></section>
  <section class="panel concept-panel"><div class="row"><h2>${t('未来报表会怎样解释收益','How a future report could explain returns')}</h2><span class="badge">${t('第 1 年 · 构造情景','Year 1 · Constructed scenario')}</span></div><p>${t('以下借用长期推演的五年反复涨跌路径，截取第一年，演示报表形式。它与上面的初始存入是两个时点。','This reporting example takes year one from the demo’s five-year repeated-cycle path. The deposit receipt above is at inception; this example is a later point.')}</p><div class="concept-metrics"><div><span>${t('情景期末资产','Scenario ending assets')}</span><strong>${money(r.nav)}</strong></div><div><span>${t('情景累计盈亏','Scenario cumulative P&L')}</span><strong class="${r.nav>=r.capital?'positive':'negative'}">${signed(r.nav-r.capital)}</strong></div></div><div class="concept-attribution">${[[t('期初股币组合持有收益','Initial shares-and-cash holding return'),r.holding],[t('静态 LP 相对持有的差额','Static LP difference vs holding'),r.il],[t('区间管理与再部署差额','Range management and redeployment'),r.management],[t('累计手续费','Cumulative fees'),r.fees]].map(([label,value])=>`<div><span>${label}</span><b class="${value>=0?'positive':'negative'}">${signed(value)}</b></div>`).join('')}<div class="concept-sum"><span>${t('合计 = 期末资产 − 初始本金','Total = ending assets − starting capital')}</span><b>${signed(r.nav-r.capital)}</b></div></div><details class="concept-details"><summary>${t('示例计算口径','Example assumptions')}</summary><div><p>${t('复用现有 AMM 模拟：Core 14%、Active 卖出 37.3%、买入 14% 的费用 APR 假设，仅对有效区间内的 LP 资本计费，按年检查复投。上述四项合计为盈亏，手续费已包含在资产中。','Uses the existing AMM simulator: fee APR assumptions of 14% Core, 37.3% Active exits and 14% Core accumulation, accruing only on in-range LP capital, with annual reinvestment checks. The four components sum to P&L; fees are already in assets.')}</p><p>${t('路径与费用均为假设，不是金库业绩或收益预测。尚未扣除交易摩擦、未来金库管理费与申赎成本；不模拟实际份额合约。','The path and fees are assumptions, not vault performance or a return forecast. Trading friction, future vault management fees and redemption costs are excluded. No share contract is simulated.')}</p></div></details></section><div class="flow-next">${button('vault','step',0,t('修改模拟金额','Change amount'),'text-button')}${button('vault','step',2,t('看金库如何运作','Explore vault operations')+' →','primary')}</div>`;}
function vaultOperations(s){const rows=[
  [t('扫描可用池子','Discover eligible pools'),t('筛选资产、流动性、费用结构与协议风险，形成可部署清单。','Screen assets, liquidity, fee structures and protocol risks to build a deployment universe.')],
  [t('定期复核估值','Review company valuations'),t('财报与新闻持续进入研究流程；确认经营变化后更新三情景边界。','Feed filings and news into research; update scenario boundaries when business changes are verified.')],
  [t('生成受约束的方案','Build a constrained proposal'),t('AI 提议区间与仓位；规则检查集中度、现金储备和单次调仓额度。','AI proposes ranges and positions. Rules check concentration, reserves and per-action limits.')],
  [t('预检后执行','Execute after preflight'),t('检查报价、流动性与授权，再通过 Solana 协议适配器执行；异常则暂停。','Check quotes, liquidity and permissions, then execute through Solana protocol adapters. Pause on exceptions.')],
  [t('对账，再进入下一轮','Reconcile and repeat'),t('归集费用、更新份额净值与归因，处理申赎，并将结果反馈给下一轮复核。','Account for fees, update NAV and attribution, process redemptions and feed results into the next review.')]
];const response={range:[t('规则内调仓','Rebalance within the mandate'),t('先确认估值逻辑未变，再判断收回 LP、保留股票或重设区间；不是碰到价格线就无条件买卖。','First confirm the valuation thesis is intact, then consider withdrawing an LP, holding shares or resetting ranges. A price threshold alone is not an unconditional trade.')],fundamental:[t('重审整个组合','Review the whole portfolio'),t('上调估值时可增加持股、减少退出型 LP；下调时可缩减风险敞口。超出金库授权的变更需管理流程批准。','A higher valuation may favor more shares and fewer exit LPs; a lower valuation may call for reducing exposure. Changes outside the vault mandate need governance approval.')],unverified:[t('继续观察，不立即交易','Watch first; do not trade yet'),t('留存来源并补充核实；没有确认的经营影响，就不自动改写估值与仓位。','Keep the source and seek confirmation. Without verified business impact, do not automatically rewrite valuations or positions.')]};return `<section class="panel concept-panel"><div class="row"><h2>${t('金库的持续运行循环','The vault operating loop')}</h2><span class="badge">${t('拟建设流程','Planned workflow')}</span></div><ol class="concept-list numbered">${rows.map(([title,body],i)=>`<li><span class="step-number">0${i+1}</span><div><b>${title}</b><p>${body}</p></div></li>`).join('')}</ol><div class="concept-loop">↻ ${t('研究 → 决策 → 执行 → 核算 → 复核','Research → Decision → Execution → Accounting → Review')}</div></section><section class="panel concept-panel">${events('vault',s)}<div class="concept-response" role="status"><b>${response[s.event][0]}</b><p>${response[s.event][1]}</p></div><details class="concept-details"><summary>${t('如何嵌入 DeFi，以及如何退出','DeFi integration and withdrawals')}</summary><div><p>${t('拟通过独立适配器接入 Solana 的 LP 协议，先从本案例使用的 Raydium 方向验证，再逐一评估其他协议。共同的估值与风控层不依赖单一池子。','Planned adapters would connect Solana LP protocols, starting with the Raydium setup used in this case, then evaluating other protocols individually. The shared valuation and risk layer would not depend on one pool.')}</p><p>${t('金库份额记录用户权益；可组合的份额资产需要额外接口与协议验证。赎回优先使用现金储备，必要时退出 LP；流动性不足时进入队列，不能预设随时无损退出。','Vault shares would record user claims. Composable share assets require additional interfaces and protocol validation. Redemptions use cash reserves first, then unwind LPs if needed; insufficient liquidity may require a queue.')}</p></div></details>${buildList('vault')}</section>`;}

function agentSetup(s){return `<section class="panel concept-panel"><h2>${t('从你的资产与目标开始','Start with your asset and objective')}</h2><form data-concept-form="agent" data-concept-stage="setup"><label class="concept-field" for="agent-asset">${t('股票 / 公司标识','Stock / company symbol')}<input id="agent-asset" name="asset" type="text" required maxlength="12" pattern="[A-Za-z][A-Za-z0-9.\-]{0,11}" value="${esc(s.draftAsset)}" data-concept-kind="agent" data-concept-field="draftAsset" autocomplete="off"><small>${t('CIRCLE 可查看历史模板；其他标识仅展示新资产 Setup 流程','CIRCLE has a historical template; other symbols preview the new-asset setup workflow only')}</small></label>${amountField('agent',s)}<label class="concept-field" for="agent-goal">${t('持有目标','Holding objective')}<select id="agent-goal" name="goal" data-concept-kind="agent" data-concept-field="draftGoal">${options([['growth',t('偏长期持股','Favor long-term share exposure')],['income',t('偏手续费现金流','Favor fee cash flow')]],s.draftGoal)}</select></label><button class="primary" type="submit">${t('预览我的策略','Preview my strategy')} →</button></form></section><section class="panel concept-panel"><h2>${t('新股票如何建立研究基础','How a new asset gets a research foundation')}</h2><div class="concept-route">${t('提供财报与研究资料 → 匹配估值方法 → 建立三情景 → 设置跟踪规则','Supply filings & research → Select valuation method → Build scenarios → Set monitoring rules')}</div><p>${t('平台将接收研报、电话会议与公司数据，经 AI 与金融 Skill 整理来源和假设。每家公司采用适合其经营逻辑的估值方法，而不是直接套用 CIRCLE 的模型。','The platform would accept research reports, earnings calls and company data. AI and financial Skills would organize sources and assumptions, using a valuation method suited to each business rather than reusing Circle’s model indiscriminately.')}</p><p class="flow-caption">${t('此处没有上传或研究生成功能；用标识体验未来的接入流程','Uploads and research generation are not implemented here. Use a symbol to preview the onboarding flow.')}</p></section>`;}
function agentPlan(s){return `<section class="panel concept-panel"><div class="row"><h2>${esc(s.asset)} · ${t('策略预览','Strategy preview')}</h2><span class="badge">${s.asset==='CIRCLE'?t('历史模板 + 给定目标','Historical template + preset target'):t('待建立研究','Research setup needed')}</span></div>${s.asset==='CIRCLE'?`<p>${t('以下比例是演示用的目标假设；区间借用 2026.08.24 历史 AI 提案，并非本次实时生成或优化。','Weights below are preset illustrative targets. Ranges use the August 24, 2026 AI proposal; they are not generated or optimized live.')}</p>${allocation(s.amount,CONCEPT_GOALS[s.goal])}<div class="concept-ranges"><span>Core LP <b>$58–172.95</b></span><span>Active LP <b>$90–115</b></span></div><p>${s.goal==='growth'?t('减少退出型 LP，保留更多股票上行敞口，同时接受更大的股价波动。','Reduce exit-oriented LPs and retain more share exposure, while accepting more price volatility.'):t('让更多资金参与 LP 费用，但可能更早换成现金，在持续上涨时落后于持股。','Allocate more to LP fees, with the trade-off of earlier conversion to cash and potential underperformance during sustained rallies.')}</p><button class="text-button" data-doc="ai_decision">${t('查看历史 AI 提案','Read the historical AI proposal')} ↗</button>`:`<div class="concept-response"><b>${t('先建立模型，再给区间','Build the model before proposing ranges')}</b><p>${t('这个资产尚无已核实的研究与链上池子映射，因此不展示虚构估值、价格或 LP 参数。','This asset has no verified research or on-chain pool mapping here, so no valuation, price or LP parameters are fabricated.')}</p></div><ol class="concept-list"><li>${t('接入有日期的财务资料与研究报告','Import dated financial inputs and research')}</li><li>${t('匹配公司估值方法，审核三情景假设','Select a valuation method and review scenario assumptions')}</li><li>${t('核实链上资产与池子，生成受约束的候选','Verify the on-chain asset and pool, then build a constrained candidate')}</li></ol>`}</section><section class="panel concept-panel"><h2>${t('你决定由谁执行','You choose who executes')}</h2><form data-concept-form="agent" data-concept-stage="permissions"><fieldset class="concept-modes"><legend>${t('执行方式','Execution mode')}</legend>${[['manual',t('手动确认','Confirm manually'),t('Agent 提案，你逐笔审阅与签名','Agent proposes; you review and sign each transaction')],['agent',t('有限授权 Agent','Delegate within limits'),t('规则内自动执行，重大变化重新确认','Automate within limits; review material changes')]].map(([value,label,body])=>`<label><input type="radio" name="mode" value="${value}" ${s.draftMode===value?'checked':''} data-concept-kind="agent" data-concept-field="draftMode"><span><b>${label}</b><small>${body}</small></span></label>`).join('')}</fieldset><label class="concept-field" for="agent-limit">${t('Agent 单次调仓上限 · 组合净值占比','Agent per-action limit · % of portfolio NAV')}<select id="agent-limit" name="limit" data-concept-kind="agent" data-concept-field="draftLimit">${options([[5,'5%'],[10,'10%'],[20,'20%']],s.draftLimit)}</select><small>${t('仅用于 Agent 模式；演示动作将使用组合的 8%','Applies to Agent mode; the example action uses 8% of the portfolio')}</small></label><div class="concept-permissions">${t('限定本资产与已批准协议 · 不允许任意转账 · 可暂停或撤销','Only this asset and approved protocols · No arbitrary transfers · Pause or revoke')}</div><button type="submit" class="primary">${t('预览运行控制台','Preview the operating console')} →</button><p class="flow-caption">${t('权限只保存在本地演示状态；没有钱包签名或真实授权','Permissions exist only in this local preview. No wallet signature or real authorization.')}</p></form></section>`;}
function agentConsole(s){const key=agentDecision(s),replies={
  'not-authorized':[t('尚未配置演示权限','Preview permissions not configured'),t('返回方案页选择执行方式','Choose an execution mode on the plan page')],
  paused:[t('已暂停演示任务','Preview tasks paused'),t('新事件继续展示，执行流程保持暂停。','Events remain visible, but the execution workflow stays paused.')],
  'needs-research':[t('等待研究与资产核实','Waiting for research and asset verification'),t('先补齐研究底稿、估值模型与池子映射，不能仅凭标识开始自动交易。','Financial inputs, a valuation model and pool mapping are required before automation; a symbol alone is insufficient.')],
  watch:[t('观察，不改仓','Watch; leave positions unchanged'),t('先核实来源与经营影响；未确认的新闻不会直接改写估值或触发交易。','Verify the source and business impact. Unconfirmed news does not directly change valuations or trigger trades.')],
  review:[t('超出日常规则，交回用户复核','Outside routine rules: return to user review'),t('先修订三情景估值，再评估全组合变化。即使额度足够，也不沿用旧授权自动处理重大经营变化。','Revise valuation scenarios, then reassess the whole portfolio. Material business changes require renewed review even if the action limit is sufficient.')],
  manual:[t('生成操作清单，等待你签名','Prepare a checklist; wait for your signature'),t('估值逻辑不变，示例拟调整 8% 的组合。你审阅目标区间与库存变化，再在钱包中逐笔确认。','With the valuation thesis unchanged, the example proposes reallocating 8% of the portfolio. Review ranges and inventory changes, then confirm each transaction in your wallet.')],
  'over-limit':[t('超过授权额度，暂停执行','Above the limit: hold execution'),t('示例调仓需要 8%，高于当前 5% 上限。保留提案，等待用户重新确认。','The 8% example action exceeds the current 5% limit. Keep the proposal and wait for renewed user approval.')],
  'within-limit':[t('额度内，进入交易预检','Within limits: proceed to preflight'),t('示例拟调整 8%，低于当前上限；仍须检查报价、滑点、余额与协议状态，通过后才可执行并对账。','The 8% example action is within the limit. Quotes, slippage, balances and protocol status must still pass preflight before execution and reconciliation.')]
};return `<section class="panel concept-panel"><div class="row"><h2>${esc(s.asset)} · ${t('Agent 运行控制台','Agent operating console')}</h2><span class="badge">${t('本地流程模拟','Local workflow simulation')}</span></div><div class="concept-receipt"><span>${t('演示资金','Preview capital')}</span><b>${money(s.amount)}</b><span>${t('执行方式','Execution mode')}</span><b>${s.mode==='manual'?t('逐笔确认','Per-transaction confirmation'):t('Agent 有限授权','Bounded Agent delegation')}</b><span>${t('单次额度','Per-action cap')}</span><b>${s.mode==='agent'?s.limit+'%':t('每次由你确认','You confirm each time')}</b></div><div class="concept-route">${t('新闻 / 财报 / 仓位 → 更新研究 → 复核候选 → 权限检查 → 预检与执行 → 核算反馈','News / filings / positions → Research → Candidate review → Permission checks → Preflight & execution → Reconciliation')}</div>${events('agent',s)}<div class="concept-response" role="status"><span class="eyebrow">${s.ran?t('模拟检查结果','SIMULATED CHECK RESULT'):t('预期处理方式','EXPECTED RESPONSE')}</span><h3>${replies[key][0]}</h3><p>${replies[key][1]}</p>${s.ran?`<small>${t('本次仅检查演示规则，未生成或发送链上交易','Only preview rules were evaluated. No on-chain transaction was built or sent.')}</small>`:''}</div><div class="concept-actions">${button('agent','run','',t('模拟检查一次','Simulate a check'),'primary',s.paused)}${button('agent','pause','',s.paused?t('恢复演示任务','Resume preview'):t('暂停演示任务','Pause preview'))}${button('agent','revoke','',t('重设演示权限','Reset preview permissions'),'text-button')}</div>${buildList('agent')}</section>`;}

export function conceptPage(kind,ui){if(!['vault','agent'].includes(kind))throw new Error('Unknown concept');const s=ui[kind];return `<div class="concept-page"><button class="text-button concept-back" data-go="future">← ${t('返回未来方向','Back to what’s next')}</button><header class="flow-heading"><div class="eyebrow">${kind==='vault'?'VAULT / PRODUCT PREVIEW':'AGENT / PRODUCT PREVIEW'}</div><h1 tabindex="-1">${kind==='vault'?t('把策略，变成可参与的金库','A strategy you could access through a vault'):t('资产由你掌管，策略持续跟进','Your assets, with an ongoing strategy workflow')}</h1><p>${kind==='vault'?t('从存入、净值到长期运行，预览未来的管理方式','Preview deposits, reporting and ongoing management'):t('从研究 Setup 到执行权限，预览未来的自托管平台','Preview a self-custodial platform, from research setup to execution permissions')}</p></header><div class="concept-notice"><span>${t('交互概念预览','Interactive concept preview')}</span><p>${t('尚未上线 · 不接受入金、不执行交易；下方数据与动作均为本地演示','Not launched · No deposits or trades; all data and actions below are local previews')}</p></div>${steps(kind,s)}${kind==='vault'?[vaultSetup,vaultStatement,vaultOperations][s.step](s):[agentSetup,agentPlan,agentConsole][s.step](s)}<footer class="flow-foot">${t('未来目标：让研究与策略持续运行。实际收益仍取决于市场、费用和策略决策，也可能亏损。','The aim is continuous research and strategy operation. Actual returns still depend on markets, fees and decisions; losses are possible.')}</footer></div>`;}
